sp_widget.client_script:
/*
 * Key Limit Swap — My Requests Client Script  v2.0
 * - Search also matches donor / donee Zone Code and Group Code; every word typed must match (any order)
 * - Added c.formatDelta() and c.deltaClass() for the Limit Cascade change pills
 */
api.controller = function($scope, $window, spUtil, $location, $timeout) {
    var c = this;

    // View state
    c.data.selectedSwap     = null;
    c.data.isLoadingDetails = false;
    c.data.isCancelling     = false;
    c.data.isFetchingSwaps  = false;

    // Filters & pagination
    c.searchSwap   = '';
    c.typeFilter   = '';
    c.listFilter   = 'pending';
    c.sapFilter    = '';          // '' | 'success' | 'pending' | 'failed'
    c.scope        = 'mine';
    c.currentPage  = 1;
    c.itemsPerPage = 10;
    c.pendingCount = 0;
    c.historyCount = 0;

    // Upload / SAP retry state
    c.isUploadingFile = false;
    c.sapRetrying     = false;
    c.sapRetryMsg     = '';
    var BLOCKED_EXT = ['exe', 'bat', 'cmd', 'com', 'msi', 'sh', 'ps1', 'vbs', 'js', 'jar', 'scr', 'dll'];

    // ---------- Formatters ----------
    c.formatINR = function(val) {
        if (val === undefined || val === null || val === '') return '0.00';
        var num = parseFloat(val);
        if (isNaN(num)) return '0.00';
        return num.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };
    // money cell: shows a dash when the value is unknown
    c.money = function(val) {
        if (val === undefined || val === null || val === '') return '—';
        return '₹ ' + c.formatINR(val);
    };
    c.avail = function(p) {
        if (!p) return 0;
        return Math.max(0, (parseFloat(p.limit_before) || 0) - (parseFloat(p.outstanding) || 0));
    };
    // change pill in the Limit Cascade
    c.formatDelta = function(v) {
        if (v === null || v === undefined || isNaN(v)) return '';
        if (v > 0) return '+ ₹ ' + c.formatINR(v);
        if (v < 0) return '− ₹ ' + c.formatINR(-v);
        return 'No change';
    };
    c.deltaClass = function(v) {
        if (v > 0) return 'is-up';
        if (v < 0) return 'is-down';
        return 'is-nil';
    };
    c.getMathMin = function(a, b) { return Math.min(a, b); };
    c.go = function(pageId) { $window.location.href = '?id=' + pageId; };

    var TAG_CLASS = {
        'intra-region': 'st-a',
        'inter-region': 'st-b',
        'inter-zone': 'st-d',
        'inter-segment': 'st-e'
    };
    c.tagCls = function(type) {
        return TAG_CLASS[String(type || '').toLowerCase()] || 'st-x';
    };

    function isPending(item) {
        return !!item && (item.internal === 'pending' || item.internal === 'work');
    }

    c.updateCounts = function() {
        var rows = c.data.rows || [];
        c.pendingCount = rows.filter(isPending).length;
        c.historyCount = rows.filter(function(i) { return !isPending(i); }).length;
    };

    c.setFilter = function(filterType) {
        c.listFilter = filterType;
        c.currentPage = 1;
    };

    // ---------- SAP quick filters ----------
    c.setSapFilter = function(status) {
        c.sapFilter = (c.sapFilter === status) ? '' : status;
        c.currentPage = 1;
    };
    c.countBySap = function(status) {
        return (c.data.rows || []).filter(function(b) { return (b.sap_status || 'na') === status; }).length;
    };
    c.hasSapStats = function() {
        return (c.data.rows || []).some(function(b) { return b.sap_status && b.sap_status !== 'na'; });
    };
    c.clearAllFilters = function() {
        c.searchSwap = '';
        c.sapFilter = '';
        c.typeFilter = '';
        c.currentPage = 1;
    };

    // ---------- List filtering / paging ----------
    function hay(b) {
        if (!b._hay) {
            b._hay = [b.number, b.gp, b.group, b.requester,
                      b.donee_site, b.donee_zone_code, b.donee_group,
                      b.donor_site, b.donor_zone_code, b.donor_group].join(' ').toLowerCase();
        }
        return b._hay;
    }
    function matchesSearch(b, query) {
        var words = String(query || '').toLowerCase().split(/\s+/).filter(Boolean);
        if (!words.length) return true;
        var h = hay(b);
        return words.every(function(w) { return h.indexOf(w) > -1; });
    }

    c.getFilteredSwaps = function() {
        var arr = c.data.rows || [];
        if (c.listFilter === 'pending') arr = arr.filter(isPending);
        else if (c.listFilter === 'completed') arr = arr.filter(function(b) { return !isPending(b); });
        else arr = arr.slice();

        if (c.typeFilter) {
            arr = arr.filter(function(b) { return (b.swap_type || '').toLowerCase() === c.typeFilter.toLowerCase(); });
        }
        if (c.sapFilter) {
            arr = arr.filter(function(b) { return (b.sap_status || 'na') === c.sapFilter; });
        }
        if (c.searchSwap) {
            arr = arr.filter(function(b) { return matchesSearch(b, c.searchSwap); });
        }
        return arr;
    };

    c.getPaginatedSwaps = function() {
        var filtered = c.getFilteredSwaps();
        var start = (c.currentPage - 1) * c.itemsPerPage;
        return filtered.slice(start, start + c.itemsPerPage);
    };
    c.totalPages = function() {
        return Math.ceil(c.getFilteredSwaps().length / c.itemsPerPage) || 1;
    };
    c.changePage = function(delta) {
        var next = c.currentPage + delta;
        if (next < 1 || next > c.totalPages()) return;
        c.currentPage = next;
    };

    // ---------- SAP send-back helpers ----------
    c.sbClass = function(status) {
        var s = (status || '').toLowerCase();
        if (s === 'success' || s === 'processed') return 'approved';
        if (s === 'failed') return 'rejected';
        return 'pending';
    };
    c.getSapSiteRows = function() {
        var list = (c.data.detail && c.data.detail.sendBackList) || [];
        var seen = {}, out = [];
        list.forEach(function(r) {
            var k = (r.customer_code || 'ALL') + '|' + (r.credit_segment || 'ALL');
            if (seen[k]) return;
            seen[k] = true;
            out.push(r);
        });
        return out;
    };

    // ---------- Master list ----------
    c.fetchSwapList = function() {
        c.data.isFetchingSwaps = true;
        c.currentPage = 1;
        c.server.get({ action: 'list', scope: c.scope }).then(function(r) {
            c.data.isFetchingSwaps = false;
            c.data.rows = (r.data && r.data.rows) ? r.data.rows : [];
            c.updateCounts();
        }).catch(function() {
            c.data.isFetchingSwaps = false;
            spUtil.addErrorMessage('Unable to load requests. Please try again.');
        });
    };

    // ---------- Details ----------
    c.viewDetails = function(swap) {
        if (!swap) return;
        c.data.selectedSwap = swap;
        c.data.detail = null;
        c.data.isLoadingDetails = true;
        c.sapRetryMsg = '';
        $location.search('sys_id', swap.sys_id);

        c.server.get({ action: 'detail', sys_id: swap.sys_id }).then(function(r) {
            c.data.isLoadingDetails = false;
            if (!r.data || r.data.serverError || !r.data.detail) {
                spUtil.addErrorMessage((r.data && r.data.serverError) || 'Unable to load this request.');
                c.goBack();
                return;
            }
            c.data.detail = r.data.detail;
            c.data.selectedSwap = r.data.detail;
            $window.scrollTo(0, 0);
        }).catch(function() {
            c.data.isLoadingDetails = false;
            spUtil.addErrorMessage('Unable to load this request.');
            c.goBack();
        });
    };

    c.goBack = function() {
        c.data.selectedSwap = null;
        c.data.detail = null;
        c.data.serverError = '';
        c.sapRetryMsg = '';
        $location.search('sys_id', null);
        if (!c.data.rows || !c.data.rows.length) c.fetchSwapList();
    };

    // ---------- SAP retry (admin only) ----------
    c.retrySap = function(swap) {
        if (c.sapRetrying || !swap || !c.data.isAdmin) return;
        if (!confirm('Retry the SAP update for ' + swap.number + '?')) return;

        c.sapRetrying = true;
        c.sapRetryMsg = '';
        c.server.get({ action: 'retry_sap', sys_id: swap.sys_id }).then(function(resp) {
            c.sapRetrying = false;
            var d = resp.data || {};
            c.sapRetryMsg = d.retryResult ? d.retryResult.message : '';
            if (d.sap) angular.extend(c.data.selectedSwap, d.sap);
            if (d.sendBackList && c.data.detail) c.data.detail.sendBackList = d.sendBackList;
            if (d.retryResult && d.retryResult.ok) c.pollSap(swap.sys_id, 4);
        }).catch(function() {
            c.sapRetrying = false;
            c.sapRetryMsg = 'Could not submit retry. Please try again.';
        });
    };

    c.pollSap = function(sysId, tries) {
        $timeout(function() {
            c.server.get({ action: 'get_sap_status', sys_id: sysId }).then(function(resp) {
                var d = resp.data || {};
                if (d.sap && c.data.selectedSwap && c.data.selectedSwap.sys_id === sysId) {
                    angular.extend(c.data.selectedSwap, d.sap);
                }
                if (d.sendBackList && c.data.detail) c.data.detail.sendBackList = d.sendBackList;
                var stillRunning = d.sap && d.sap.sap_status === 'pending';
                if (stillRunning && tries > 1) c.pollSap(sysId, tries - 1);
                else c.sapRetryMsg = '';
            });
        }, 15000);
    };

    // ---------- Document upload ----------
    c.pickFile = function() {
        var el = document.getElementById('swapAttachmentUpload');
        if (el) el.click();
    };

    function uploadFile(file, element) {
        if (!file || !c.data.selectedSwap) return;
        var ext = (file.name.split('.').pop() || '').toLowerCase();
        if (BLOCKED_EXT.indexOf(ext) > -1) {
            spUtil.addErrorMessage('Executable / script files are not allowed.');
            element.value = '';
            return;
        }
        if (file.size > 5 * 1024 * 1024) {
            spUtil.addErrorMessage('File size exceeds 5MB limit.');
            element.value = '';
            return;
        }

        c.isUploadingFile = true;
        $scope.$applyAsync();
        var reader = new FileReader();
        reader.onload = function(e) {
            var base64Data = String(e.target.result).split(',')[1];
            c.server.get({
                action: 'upload_document',
                sys_id: c.data.selectedSwap.sys_id,
                fileName: file.name,
                fileType: file.type || 'application/octet-stream',
                fileData: base64Data
            }).then(function(res) {
                c.isUploadingFile = false;
                element.value = '';
                if (res.data && res.data.serverError) {
                    spUtil.addErrorMessage(res.data.serverError);
                    return;
                }
                spUtil.addInfoMessage('Document uploaded successfully.');
                if (c.data.detail) c.data.detail.attachments = res.data.attachments || [];
            }).catch(function() {
                c.isUploadingFile = false;
                element.value = '';
                spUtil.addErrorMessage('Failed to upload document.');
            });
        };
        reader.onerror = function() {
            c.isUploadingFile = false;
            element.value = '';
            spUtil.addErrorMessage('Unable to read the file.');
            $scope.$applyAsync();
        };
        reader.readAsDataURL(file);
    }

    function bindUpload() {
        var input = document.getElementById('swapAttachmentUpload');
        if (input && !input._clmBound) {
            input._clmBound = true;
            input.addEventListener('change', function(e) {
                uploadFile(e.target.files[0], input);
            });
        }
    }
    $scope.$watch(function() { return c.data.detail; }, function(d) {
        if (d) $timeout(bindUpload, 0);
    });

    // ---------- Cancel ----------
    c.cancelRequest = function(swap) {
        if (!swap || c.data.isCancelling) return;
        if (!confirm('Are you sure you want to cancel request ' + swap.number + '? Pending approvals will be terminated.')) return;

        c.data.isCancelling = true;
        c.server.get({ action: 'cancel_swap', sys_id: swap.sys_id }).then(function(response) {
            c.data.isCancelling = false;
            var d = response.data || {};
            if (d.success) {
                spUtil.addInfoMessage('Request ' + swap.number + ' has been cancelled.');
                c.data.rows = [];
                c.goBack();
                c.fetchSwapList();
            } else {
                spUtil.addErrorMessage(d.message || 'Unable to cancel request.');
            }
        }).catch(function() {
            c.data.isCancelling = false;
            spUtil.addErrorMessage('Unable to cancel request.');
        });
    };

    // ---------- Init ----------
    c.$onInit = function() {
        // a stale ?sys_id= link that failed to load must not stay in the URL
        if (c.data.linkError) { $location.search('sys_id', null); }

        c.data.rows = c.data.rows || [];
        c.updateCounts();
        // opened directly with ?sys_id=...
        if (c.data.detail) {
            c.data.selectedSwap = c.data.detail;
            $timeout(bindUpload, 0);
        }
    };
};

sp_widget.css:
/* =====================================================================
   Key Limit Swap — My Requests CSS  v2.0
   - Added Zone Code pill (.clm-ls-seg-zone), pill labels and pill row (.clm-ls-pills)
   - Profile head identifiers (.clm-ls-id) and Depot · Region · Zone strip (.clm-ls-terr)
   - Limit Cascade compact table (.clm-lc-*), same look as the request page
===================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

/* ---------------------------------------------------------------------
0. Page shell + header banner
--------------------------------------------------------------------- */
.clm-ls, .clm-ls *, .clm-ls *::before, .clm-ls *::after { box-sizing:border-box; }
.clm-ls { background:white; padding:24px 32px; border-radius:8px; color:#1a1a1a; font-size:13px; }

.clm-hero {
  position:relative; overflow:hidden; border-radius:12px; padding:26px 30px; min-height:132px;
  display:flex; align-items:center; justify-content:space-between; gap:20px; flex-wrap:wrap;
  box-shadow:0 10px 28px rgba(122,16,18,.25);
  background:
    linear-gradient(90deg, #7A1012 0%, #9E1715 40%, rgba(158,23,21,.88) 52%, rgba(158,23,21,.35) 68%, rgba(158,23,21,0) 82%),
    radial-gradient(circle at 72% 100%, #F3CE52 0 30px, #7A1012 30px 33px, #F9A04A 33px 44px, #7A1012 44px 47px, #F3712A 47px 58px, transparent 58px),
    repeating-conic-gradient(from -90deg at 72% 100%, #F3CE52 0deg 7deg, #F3712A 7deg 14deg, #9E1715 14deg 21deg, #DA1D26 21deg 28deg),
    #9E1715;
}

.clm-hero-breadcrumb { display:flex; align-items:center; gap:8px; margin-bottom:10px; font-size:13px; font-weight:600; color:#fbe3cf; flex-wrap:wrap; }
.clm-hero-breadcrumb .clm-breadcrumb-link { color:#F3CE52; text-decoration:none; display:inline-flex; align-items:center; gap:5px; cursor:pointer; }
.clm-hero-breadcrumb .clm-breadcrumb-link:hover { text-decoration:underline; opacity:0.9; }
.clm-hero-breadcrumb .clm-breadcrumb-sep { font-size:12px; opacity:0.7; color:#ffffff; }
.clm-hero-breadcrumb .clm-breadcrumb-curr { color:#ffffff; font-weight:700; }

.clm-hero-text { position:relative; z-index:1; flex:1 1 420px; min-width:0; }
.clm-hero-bar { width:44px; height:6px; border-radius:3px; background:linear-gradient(90deg,#F3CE52,#F3712A); margin-bottom:12px; }
.clm-hero-title { margin:0; font-size:26px; font-weight:700; line-height:1.25; color:#ffffff; }
.clm-hero-accent { color:#F3CE52; }
.clm-hero-sub { margin:6px 0 0; font-size:15px; color:#fbe3cf; }
.clm-hero-tag {
  display:inline-flex; align-items:center; gap:6px; margin-top:12px; padding:4px 10px; border-radius:12px;
  background:rgba(122,16,18,.6); border:1px solid rgba(243,206,82,.6); color:#F3CE52; font-size:12px; font-weight:700;
}
.clm-hero-chips { display:flex; flex-wrap:wrap; gap:8px; margin-top:14px; }
.clm-hero-chip {
  display:inline-flex; align-items:center; gap:6px; padding:4px 10px; border-radius:12px;
  background:#ffffff; border:1px solid #ffffff; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap;
}
.clm-hero-chip-k { font-weight:400; color:#5a6a7a; }

.clm-hero-side { position:relative; z-index:1; display:flex; flex-direction:column; align-items:flex-end; gap:12px; }
.clm-hero-actions-row { display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:flex-end; }
.clm-hero-btn {
  display:inline-flex; align-items:center; gap:8px; padding:9px 18px; border-radius:8px; cursor:pointer;
  background:#F3CE52; color:#7A1012; border:2px solid #7A1012; font-size:14px; font-weight:700;
  box-shadow:0 0 0 2px rgba(243,206,82,.35);
}
.clm-hero-btn:hover { background:#ffdf6e; }
.clm-hero-btn[disabled] { opacity:.6; cursor:not-allowed; }
.clm-hero-stat { padding:12px 20px; border-radius:10px; background:rgba(122,16,18,.92); border-left:4px solid #F3CE52; text-align:right; }
.clm-hero-stat-v { font-size:34px; font-weight:700; line-height:1.1; letter-spacing:1px; color:#F3CE52; white-space:nowrap; }
.clm-hero-stat-v.is-amount { font-size:26px; letter-spacing:.5px; }
.clm-hero-stat-k { margin-top:4px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#fbd9bd; }

/* ---------------------------------------------------------------------
1. Section
--------------------------------------------------------------------- */
.clm-section { margin-top:20px; background:#fff; border:1px solid #e0e6ed; border-radius:10px; padding:28px 32px; }
.clm-section-title {
  display:flex; align-items:center; gap:12px; margin-bottom:4px;
  font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px;
}
.clm-section-num {
  width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a; flex-shrink:0;
  font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center;
}
.clm-ls-gap { margin-top:32px; }
.clm-ls-mt0 { margin-top:0; }
.clm-ls-mb16 { margin-bottom:16px; }

/* ---------------------------------------------------------------------
2. Card (block) + chips
--------------------------------------------------------------------- */
.clm-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-block-head {
  display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea;
}
.clm-block-title {
  display:flex; align-items:center; gap:10px; font-size:13px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.8px;
}
.clm-block-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-block-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-block-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-chip {
  display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff;
  border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap;
}
.clm-chip-k { font-weight:400; color:#5a6a7a; }
.clm-mr-clear { padding:4px 10px; border:1px solid #cdd4dc; border-radius:12px; background:#ffffff; color:#c0392b; font-size:12px; font-weight:700; cursor:pointer; }
.clm-mr-clear:hover { background:#fef5f4; border-color:#f5c2bc; }
.clm-tw-body { padding:18px 20px; }

/* error / deviation card */
.clm-block-dev { border-color:#f3c2bc; }
.clm-block-dev .clm-block-head { background:#fef5f4; border-bottom:none; }
.clm-block-dev .clm-block-title { color:#b3261e; }
.clm-block-dev .clm-block-title::before { background:#E23D28; }

/* ---------------------------------------------------------------------
3. SAP Sync Filter & Badges
--------------------------------------------------------------------- */
.clm-mr-sap-stats { margin-top:14px; padding:14px 16px; background:#ffffff; border:1px solid #dde3ea; border-radius:8px; }
.clm-mr-sap-title { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:0.6px; margin-bottom:10px; }
.clm-mr-sap-tiles { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:10px; }
.clm-mr-sap-tile {
  display:flex; flex-direction:column; align-items:flex-start; gap:2px; padding:10px 12px; background:#ffffff;
  border:1px solid #dde3ea; border-left:4px solid #cdd4dc; border-radius:6px; cursor:pointer; font-family:inherit; text-align:left;
  transition:box-shadow .15s ease, transform .15s ease, background .15s ease;
}
.clm-mr-sap-tile:hover { box-shadow:0 4px 10px rgba(0,0,0,0.05); transform:translateY(-1px); }
.clm-mr-sap-tile.is-active { background:#fffcf0; border-color:#F3D54E; box-shadow:0 0 0 2px rgba(243,213,78,.35); }
.clm-mr-sap-tile.sap-success { border-left-color:#27ae60; }
.clm-mr-sap-tile.sap-pending { border-left-color:#E87722; }
.clm-mr-sap-tile.sap-failed  { border-left-color:#E23D28; }
.clm-mr-sap-k { font-size:11px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:0.5px; }
.clm-mr-sap-v { font-size:20px; font-weight:700; color:#1a1a1a; line-height:1.1; }
.clm-mr-sap-tile.sap-success .clm-mr-sap-v { color:#1e8449; }
.clm-mr-sap-tile.sap-pending .clm-mr-sap-v { color:#b9650f; }
.clm-mr-sap-tile.sap-failed  .clm-mr-sap-v { color:#c0392b; }

.clm-badge { display:inline-block; padding:4px 10px; border-radius:4px; font-size:11px; font-weight:700; letter-spacing:0.5px; text-transform:uppercase; }
.clm-status-approved { background:#eafaf1; color:#1e8449; border:1px solid #a9dfbf; }
.clm-status-rejected { background:#fef5f4; color:#c0392b; border:1px solid #fadbd8; }
.clm-status-pending  { background:#eaf4fb; color:#1a5276; border:1px solid #aed6f1; }

.clm-sap { border:1px solid transparent; }
.clm-sap.sap-success, .clm-sap-banner.sap-success { background:#eafaf1; color:#1e8449; border-color:#a9dfbf; }
.clm-sap.sap-failed,  .clm-sap-banner.sap-failed  { background:#fef5f4; color:#c0392b; border-color:#f5c2bc; }
.clm-sap.sap-pending, .clm-sap-banner.sap-pending { background:#fffcf0; color:#8a6100; border-color:#F9E79F; }
.clm-sap-clickable { cursor:pointer; }
.clm-sap-clickable:hover { transform:translateY(-1px); }

.clm-sap-banner { display:flex; gap:12px; align-items:flex-start; padding:14px 24px; border:1px solid; border-radius:6px; margin-top:16px; }
.clm-sap-ico { font-size:20px; line-height:1.2; }
.clm-sap-title { font-size:13px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; }
.clm-sap-msg { font-size:13px; margin-top:2px; color:#1a1a1a; }
.clm-sap-err { font-size:11.5px; margin-top:6px; color:#5a6a7a; font-family:monospace; white-space:pre-wrap; }
.clm-sap-actions { margin-top:10px; }
.clm-sap-retry { background:#c0392b; color:#fff; height:36px; padding:0 16px; border:none; border-radius:4px; font-weight:700; cursor:pointer; }
.clm-sap-retry:hover:not(:disabled) { background:#a93226; }
.clm-sap-note { margin-top:8px; font-size:12px; font-weight:600; color:#5a6a7a; }

.clm-sb-row { padding:12px 14px; margin-bottom:10px; background:#fafbfc; border:1px solid #dde3ea; border-radius:6px; }
.clm-sb-row:last-child { margin-bottom:0; }
.clm-sb-top { display:flex; align-items:center; justify-content:space-between; gap:8px; }
.clm-sb-when { font-size:11.5px; color:#7f8c9a; }
.clm-sb-meta { display:flex; flex-wrap:wrap; gap:4px 18px; margin-top:8px; font-size:12.5px; }
.clm-sb-meta .k { color:#7f8c9a; margin-right:4px; }
.clm-sb-err { margin-top:8px; padding:7px 10px; border-radius:6px; background:#fef5f4; border:1px solid #f5c2bc; font-size:12px; color:#8f1d16; }

/* ---------------------------------------------------------------------
4. Data table
--------------------------------------------------------------------- */
.clm-table-wrap { overflow-x:auto; border:1px solid #dde3ea; border-radius:8px; background:#fff; }
.clm-table { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; }
.clm-table th {
  background:#eef1f5; color:#2b3440; padding:12px 14px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap; border:1px solid #dde3ea;
}
.clm-table td { padding:14px; color:#1a1a1a; text-align:center; white-space:nowrap; border:1px solid #e6eaef; vertical-align:middle; }
.clm-table tr > :first-child { border-left:0; text-align:left; }
.clm-table tr > :last-child  { border-right:0; }
.clm-table thead tr:first-child th { border-top:0; }
.clm-table tbody tr:last-child td  { border-bottom:0; }
.clm-table .grp { border-left:2px solid #c9d1db !important; }
.clm-table .num { text-align:right; }

.clm-table tr.super th { letter-spacing:1px; padding:11px 14px; }
.clm-table th.bg-code  { background:#e3eefa; color:#0b5394; }
.clm-table th.bg-seg   { background:#f1f3f7; color:#3a4451; }
.clm-table th.bg-donee { background:#e6f4ea; color:#2e7d32; }
.clm-table th.bg-donor { background:#fdecea; color:#b3261e; }

.clm-cust-name { font-weight:700; color:#1a1a1a; }
.clm-cust-code { margin-top:2px; font-size:12px; font-weight:600; color:#5a6a7a; }
.v-bad { color:#c0392b !important; font-weight:700; }

/* ---------------------------------------------------------------------
5. Factor tiles + result row
--------------------------------------------------------------------- */
.clm-tw-factors { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-tw-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; min-width:0; }
.clm-tw-factor-k { font-size:12px; color:#5a6a7a; margin-bottom:4px; }
.clm-tw-factor-v { font-size:16px; font-weight:700; color:#1a1a1a; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-tw-factor-v.is-text { font-size:13.5px; white-space:normal; overflow:visible; word-break:break-word; }
.clm-tw-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; } .clm-tw-factor.is-ok  .clm-tw-factor-v { color:#1e8449; }
.clm-tw-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; } .clm-tw-factor.is-bad .clm-tw-factor-v { color:#c0392b; }

.clm-tw-res {
  display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0;
}
.clm-tw-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-tw-res-f { margin-top:3px; font-size:12px; color:#7f8c9a; }
.clm-tw-res-v { margin-left:auto; font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; white-space:nowrap; }
.clm-tw-res.is-ok  { background:#f4fbf6; border-top-color:#b9e3c6; } .clm-tw-res.is-ok  .clm-tw-res-v { color:#1e8449; }
.clm-tw-res.is-bad { background:#fef5f4; border-top-color:#f5c2bc; } .clm-tw-res.is-bad .clm-tw-res-v { color:#c0392b; }

/* ---------------------------------------------------------------------
6. Status tiles (list page)
--------------------------------------------------------------------- */
.clm-ls-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-mr-stat {
  display:flex; flex-direction:column; gap:6px; padding:14px 16px; background:#fff;
  border:1px solid #dde3ea; border-top:4px solid #cdd4dc; border-radius:8px; cursor:pointer; text-align:left;
  transition:box-shadow .15s, background .15s;
}
.clm-mr-stat:hover { box-shadow:0 2px 8px rgba(0,0,0,.06); }
.clm-mr-stat:focus { outline:none; }
.clm-mr-stat-k { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-mr-stat-v { font-size:26px; font-weight:700; line-height:1.1; }
.clm-mr-stat-s { font-size:11px; color:#7f8c9a; }
.clm-mr-stat.is-active { background:#fffcf0; border-color:#F3D54E; box-shadow:0 0 0 2px rgba(243,213,78,.35); }
.clm-mr-stat.st-pending { border-top-color:#2e86c1; } .clm-mr-stat.st-pending .clm-mr-stat-v { color:#2e86c1; }
.clm-mr-stat.st-history { border-top-color:#27ae60; } .clm-mr-stat.st-history .clm-mr-stat-v { color:#27ae60; }
.clm-mr-stat.st-all     { border-top-color:#1a1a1a; } .clm-mr-stat.st-all     .clm-mr-stat-v { color:#1a1a1a; }

/* ---------------------------------------------------------------------
7. Ageing table bucket colours
--------------------------------------------------------------------- */
tr.ag-group th.safe { background:#d9eedd; color:#14532d; }  tr.ag-sub th.safe { background:#edf7ef; color:#14532d; }
tr.ag-group th.warn { background:#fde4c4; color:#7a4100; }  tr.ag-sub th.warn { background:#fff4e5; color:#7a4100; }
tr.ag-group th.risk { background:#f8d7d3; color:#8f1d16; }  tr.ag-sub th.risk { background:#fdeeec; color:#8f1d16; }
.clm-table td.zero { color:#b0b9c4; }
.clm-table td.warn-val { color:#a15a00; font-weight:700; background:#fffaf2; }
.clm-table td.risk-val { color:#b3261e; font-weight:700; background:#fff6f5; }

/* ---------------------------------------------------------------------
8. Buttons & Utilities
--------------------------------------------------------------------- */
.clm-btn {
  display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:8px 16px;
  border:1px solid transparent; border-radius:6px; font-size:13px; font-weight:700; line-height:1.2;
  cursor:pointer; white-space:nowrap; transition:background .15s, color .15s, border-color .15s;
  text-decoration:none !important;
}
.clm-btn[disabled] { opacity:.5; cursor:not-allowed; }
.clm-btn-sm   { padding:6px 12px; font-size:12px; }
.clm-btn-xs   { padding:4px 9px; font-size:11.5px; border-radius:4px; gap:4px; }
.clm-btn-reject  { background:#E23D28; color:#fff; }
.clm-btn-reject:hover:not([disabled])  { background:#b3261e; color:#fff; }
.clm-btn-ghost   { background:#fff; color:#1a1a1a; border-color:#cdd4dc; }
.clm-btn-ghost:hover:not([disabled])   { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }

.clm-ls-label { display:block; margin-bottom:6px; font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-ls-hint { margin-top:8px; font-size:12px; color:#7f8c9a; }
.clm-ls .input-group-addon { background:#fafbfc; border-color:#cfd6de; color:#7f8c9a; }
.clm-ls .form-control { display:block; width:100%; padding:7px 10px; border:1px solid #cfd6de; border-radius:6px; box-shadow:none; height:auto; min-height:36px; font-size:13px; }
.clm-ls .input-group { display:table; width:100%; border-collapse:separate; }
.clm-ls .input-group .form-control { display:table-cell; border-radius:0 6px 6px 0; }
.clm-ls .input-group-addon { display:table-cell; width:1%; padding:0 12px; border:1px solid #cfd6de; border-right:0; border-radius:6px 0 0 6px; vertical-align:middle; }

/* filter grid (search | type | scope(admin) | rows) */
.clm-ls-filter-grid { display:grid; grid-template-columns:repeat(auto-fit, minmax(170px, 1fr)); gap:16px; }
.clm-ls-filter-grid > .is-wide { grid-column:span 2; }

.clm-ls-actions { display:flex; align-items:center; justify-content:flex-end; gap:10px; flex-wrap:wrap; padding:14px 20px; background:#fafbfc; border-top:1px solid #e6eaef; }
.clm-ls-processing { font-size:12px; color:#5a6a7a; }
.clm-ls-muted { color:#7f8c9a; font-size:12.5px; }
.clm-ls-text { margin:0; white-space:pre-wrap; font-size:13px; line-height:1.6; color:#1a1a1a; }
.clm-ls-subhead { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.5px; }
.clm-ls-cmt-text { white-space:pre-wrap; }

/* loading / empty */
.clm-ls-loading { padding:40px 20px; text-align:center; color:#5a6a7a; }
.clm-ls-loading i { color:#AF272F; }
.clm-ls-loading p { margin:10px 0 0; font-weight:700; }
.clm-ls-empty { margin-top:16px; padding:40px 20px; text-align:center; background:#fafbfc; border:1px dashed #cdd4dc; border-radius:8px; }
.clm-ls-empty i { color:#27ae60; }
.clm-ls-empty h4 { margin:10px 0 4px; font-size:16px; font-weight:700; color:#1a1a1a; }
.clm-ls-empty p { margin:0; color:#5a6a7a; }

/* queue table */
.clm-ls-table-wrap { border:0; border-radius:0; }
.clm-ls-table .clm-ls-left { text-align:left; }
.clm-ls-table th, .clm-ls-table td { padding:12px 12px; }
.clm-ls-table td.clm-ls-wrap { white-space:normal; min-width:170px; }
.clm-ls-table tbody tr:hover td { background:#fffdf3; }
.clm-ls-table tbody tr.is-selected td { background:#FFF8D6; }
.clm-ls-reqno { font-size:14px; font-weight:700; color:#1a1a1a; }
.clm-ls-pan { margin-top:3px; font-size:12px; font-weight:700; color:#1a1a1a; }
.clm-ls-meta { margin-top:3px; font-size:12px; color:#5a6a7a; }
.clm-ls-meta i { width:14px; color:#8a96a3; }
.clm-ls-seg { display:inline-block; margin-top:6px; margin-right:4px; padding:2px 8px; border-radius:4px; background:#f1f3f7; border:1px solid #dde3ea; color:#3a4451; font-size:11px; font-weight:700; }
.clm-ls-seg-grp { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }

/* swap type tag (Key) */
.clm-swap-tag {
  display:inline-flex; align-items:center; padding:3px 10px; border:1px solid; border-radius:12px;
  font-size:11.5px; font-weight:700; white-space:nowrap;
}
.clm-swap-tag.st-a { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-swap-tag.st-b { background:#e3eefa; border-color:#b7d3f0; color:#0b5394; }
.clm-swap-tag.st-d { background:#fdf3e1; border-color:#f6d39a; color:#a35400; }
.clm-swap-tag.st-e { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }
.clm-swap-tag.st-x { background:#f3f4f6; border-color:#dcdfe4; color:#5a6a7a; }

/* status pill */
.clm-ls-status {
  display:inline-block; padding:4px 12px; border-radius:12px; border:1px solid; font-size:11.5px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; white-space:nowrap;
}
.clm-ls-status.st-pending   { background:#eaf3fb; color:#2e86c1; border-color:#b8d6ee; }
.clm-ls-status.st-approved  { background:#eaf7ee; color:#1e8449; border-color:#b9e3c6; }
.clm-ls-status.st-rejected  { background:#fdecea; color:#b3261e; border-color:#f5c2bc; }
.clm-ls-status.st-cancelled { background:#f3f4f6; color:#5a6a7a; border-color:#dcdfe4; }
.clm-ls-status.st-work      { background:#fff4e0; color:#a15a00; border-color:#f6d39a; }

/* pager */
.clm-ls-pager {
  display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;
  padding:12px 20px; background:#fafbfc; border-top:1px solid #dde3ea; font-size:12.5px; color:#5a6a7a;
}
.clm-ls-pager-nav { display:flex; align-items:center; gap:10px; }
.clm-ls-pager-page { font-weight:700; color:#1a1a1a; }

/* 2x2 matrix */
.clm-ls-matrix { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; margin-top:16px; align-items:stretch; }
.clm-ls-cell { margin-top:0; display:flex; flex-direction:column; min-width:0; }
.clm-ls-cell > .clm-ls-actions { margin-top:auto; }

/* attached documents */
.clm-ls-doclist { display:flex; flex-direction:column; gap:8px; }
.clm-ls-doc {
  display:flex; align-items:center; gap:12px; padding:10px 12px; border:1px solid #dde3ea; border-radius:6px;
  background:#fafbfc; color:#1a1a1a; min-width:0;
}
.clm-ls-doc:hover { border-color:#cdd4dc; background:#fff; }
.clm-ls-doc-icon {
  flex-shrink:0; width:32px; height:32px; border-radius:6px; display:flex; align-items:center; justify-content:center;
  background:#eef1f5; color:#5a6a7a; font-size:15px;
}
.clm-ls-doc-icon.is-pdf { background:#fdecea; color:#E23D28; }
.clm-ls-doc-main { flex:1 1 auto; min-width:0; display:flex; flex-direction:column; gap:2px; }
.clm-ls-doc-name { font-size:13px; font-weight:700; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.clm-ls-doc-meta { font-size:11.5px; color:#7f8c9a; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.clm-ls-doc-actions { display:inline-flex; align-items:center; gap:6px; flex-shrink:0; margin-left:auto; }
.clm-ls-upload {
  display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;
  padding:14px 20px; border-top:1px dashed #e6eaef; margin-top:auto;
}

/* auto-approved banner */
.clm-ls-autoappr {
  display:flex; align-items:center; gap:10px; padding:12px 14px; border-radius:6px;
  background:#eaf7ee; border:1px solid #b9e3c6; color:#1e8449; font-size:13px;
}
.clm-ls-autoappr i { font-size:18px; }

/* approval stepper */
.clm-ls-stepper { display:flex; align-items:flex-start; overflow-x:auto; padding:6px 0 4px; }
.clm-ls-step { position:relative; flex:1 1 0; min-width:150px; padding:0 8px; text-align:center; }
.clm-ls-step::before { content:""; position:absolute; top:16px; left:-50%; width:100%; height:2px; background:#dde3ea; z-index:0; }
.clm-ls-step:first-child::before { display:none; }
.clm-ls-step.completed::before, .clm-ls-step.current::before, .clm-ls-step.rejected::before { background:#27ae60; }
.clm-ls-step-icon {
  position:relative; z-index:1; width:34px; height:34px; margin:0 auto 8px; border-radius:50%;
  display:flex; align-items:center; justify-content:center; background:#fff; border:2px solid #cdd4dc;
  color:#8a96a3; font-size:13px; font-weight:700;
}
.clm-ls-step.completed .clm-ls-step-icon { background:#27ae60; border-color:#27ae60; color:#fff; }
.clm-ls-step.current .clm-ls-step-icon   { border-color:#2e86c1; color:#2e86c1; box-shadow:0 0 0 4px rgba(46,134,193,.18); }
.clm-ls-step.rejected .clm-ls-step-icon  { background:#E23D28; border-color:#E23D28; color:#fff; }
.clm-ls-step-name { font-size:12.5px; font-weight:700; color:#1a1a1a; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-ls-step.is-me .clm-ls-step-name { color:#AF272F; }
.clm-ls-step-role { margin-top:2px; font-size:11px; color:#5a6a7a; text-transform:uppercase; letter-spacing:.4px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-ls-step-state { margin-top:4px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.4px; color:#7f8c9a; }
.clm-ls-step.completed .clm-ls-step-state { color:#1e8449; }
.clm-ls-step.current .clm-ls-step-state   { color:#2e86c1; }
.clm-ls-step.rejected .clm-ls-step-state  { color:#b3261e; }
.clm-ls-you {
  display:inline-block; margin-top:6px; padding:2px 8px; border-radius:4px; background:#1a1a1a; color:#F3D54E;
  font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.5px;
}

/* site profile columns */
.clm-ls-cols { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px; margin-top:16px; }
.clm-ls-col { background:#f4f4f1; border:1px solid #e0e6ed; border-radius:10px; padding:20px; min-width:0; }
.clm-col-heading {
  display:flex; align-items:center; gap:8px; padding-bottom:8px; border-bottom:2px solid #F3D54E;
  font-size:15px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:.8px;
}
.clm-ls-col-donee .clm-col-heading i { color:#27ae60; }
.clm-ls-col-donor .clm-col-heading i { color:#E23D28; }
.clm-ls-flush { border:0; border-radius:0; }
.clm-ls-aging th, .clm-ls-aging td { padding:9px 10px; }
.clm-ls-aging tr.ag-group th, .clm-ls-aging tr.ag-sub th { font-size:11.5px; letter-spacing:.5px; }
.clm-ls-aging td { font-size:12.5px; }
.clm-ls-aging .clm-ls-left { text-align:left; }
.clm-ls-aging td.clm-ls-total { background:#FFF8D6; font-weight:700; }

.slide-down { animation:clmLsSlide .25s ease-out; }
@keyframes clmLsSlide { from { opacity:0; transform:translateY(-4px); } to { opacity:1; transform:translateY(0); } }

/* ---------------------------------------------------------------------
9. Responsive
--------------------------------------------------------------------- */
@media (max-width:1100px) {
  .clm-ls-cols { grid-template-columns:1fr; }
  .clm-ls-matrix { grid-template-columns:1fr; }
  .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width:991px) {
  .clm-hero-title { font-size:22px; }
  .clm-hero-side { align-items:flex-start; }
  .clm-hero-actions-row { justify-content:flex-start; }
}
@media (max-width:768px) {
  .clm-ls { padding:16px; }
  .clm-section { padding:20px 16px; }

  .clm-ls-table thead { display:none; }
  .clm-ls-table, .clm-ls-table tbody, .clm-ls-table tr, .clm-ls-table td { display:block; width:100%; }
  .clm-ls-table tr { border-bottom:6px solid #f4f5f7; }
  .clm-ls-table td {
    display:grid; grid-template-columns:38% minmax(0,1fr); column-gap:12px; align-items:start;
    text-align:right !important; white-space:normal; border:0; border-bottom:1px solid #eef1f5; padding:10px 14px;
  }
  .clm-ls-table td > * { grid-column:2; justify-self:end; }
  .clm-ls-table td.grp { border-left:0 !important; }
  .clm-ls-table td::before {
    content:attr(data-label); grid-column:1; grid-row:1 / span 6; text-align:left;
    font-size:11px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:.5px;
  }
  .clm-ls-table td.clm-ls-wrap { min-width:0; }
  .clm-ls-filter-grid > .is-wide { grid-column:auto; }
}
@media (max-width:640px) {
  .clm-hero { padding:22px 20px; }
  .clm-hero-title { font-size:20px; }
  .clm-hero-side { width:100%; }
  .clm-hero-stat { text-align:left; }
  .clm-hero-stat-v.is-amount { font-size:22px; }
  .clm-ls-stats { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-ls-stats .st-all { grid-column:1 / -1; }
  .clm-ls-filter-grid { grid-template-columns:1fr; }
  .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-tw-res-v { font-size:24px; }
  .clm-ls-col { padding:14px; }
  .clm-ls-stepper { flex-direction:column; overflow:visible; gap:14px; }
  .clm-ls-step { display:grid; grid-template-columns:34px minmax(0,1fr); column-gap:12px; min-width:0; padding:0; text-align:left; }
  .clm-ls-step::before { top:-14px; left:16px; width:2px; height:14px; }
  .clm-ls-step-icon { grid-row:1 / span 4; margin:0; }
  .clm-mr-sap-tiles { grid-template-columns:1fr; }
}

/* =====================================================================
9a. v2.0 additions — Zone Code / Group pills, territory strip, limit cascade
===================================================================== */
.clm-th-sub { margin-top:3px; font-size:10.5px; font-weight:400; color:#7f8c9a; text-transform:none; letter-spacing:0; }

/* identifier pills (Segment · Zone Code · Group) */
.clm-ls-pills { display:flex; flex-wrap:wrap; gap:4px; margin-top:6px; }
.clm-ls-pills .clm-ls-seg { margin:0; }
.clm-ls-pills .clm-ls-seg, .clm-ls-id .clm-ls-seg { white-space:nowrap; }
.clm-ls-table td.clm-ls-site { min-width:250px; }
.clm-chip-req { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-chip-req .clm-chip-k { color:inherit; opacity:.8; }
.clm-ls-seg-zone { background:#e3eefa; border-color:#b7d3f0; color:#0b5394; }
.clm-ls-pill-k { font-weight:400; opacity:.8; margin-right:2px; }

/* profile head: (code) · Zone Code · Group on one line */
.clm-block-sub.clm-ls-id { display:flex; align-items:center; flex-wrap:wrap; gap:6px; margin-top:6px; }
.clm-ls-id .clm-cust-code { margin-top:0; }
.clm-ls-id .clm-ls-seg { margin:0; }

/* Depot · Region · Zone strip */
.clm-ls-terr { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); margin-bottom:12px;
  border:1px solid #e0e6ed; border-radius:6px; background:#fff; }
.clm-ls-terr-item { padding:10px 14px; border-left:1px solid #eef1f5; min-width:0; }
.clm-ls-terr-item:first-child { border-left:none; }
.clm-ls-terr-k { font-size:11.5px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:.6px; }
.clm-ls-terr-v { margin-top:3px; font-size:13px; font-weight:700; color:#1a1a1a; text-transform:uppercase; word-break:break-word; }

/* limit cascade — compact table */
.clm-table th .fa { margin-right:4px; }
.clm-lc-table { table-layout:fixed; min-width:640px; }
.clm-lc-table td { text-align:left; white-space:normal; padding:12px 16px; }
.clm-lc-table th.clm-ls-left { text-align:left; }
.clm-lc-lvl-h { width:180px; }
.clm-lc-lvl-name { font-weight:700; color:#1a1a1a; }
.clm-lc-lvl-desc { margin-top:2px; font-size:11px; color:#7f8c9a; }
.clm-lc-code { font-size:12px; font-weight:700; color:#5a6a7a; letter-spacing:.3px; }
.clm-lc-move { display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-top:4px; }
.clm-lc-from { color:#7f8c9a; }
.clm-lc-arrow { color:#8a96a3; font-size:12px; }
.clm-lc-to { font-size:15px; font-weight:700; color:#1a1a1a; }
.clm-lc-delta { display:inline-block; padding:1px 8px; border-radius:10px; font-size:11.5px; font-weight:700; }
.clm-lc-delta.is-down { background:#fdecea; color:#b3261e; }
.clm-lc-delta.is-up   { background:#eaf7ee; color:#1e8449; }
.clm-lc-delta.is-nil  { background:#f1f3f7; color:#5a6a7a; font-weight:400; }

@media (max-width:768px) {
  .clm-ls-table .clm-ls-pills { justify-content:flex-end; }
  .clm-ls-table td.clm-ls-site { min-width:0; }
  .clm-lc-table { min-width:0; table-layout:auto; }
  .clm-lc-table thead { display:none; }
  .clm-lc-table, .clm-lc-table tbody, .clm-lc-table tr, .clm-lc-table td { display:block; width:100%; }
  .clm-lc-table tbody tr { padding:10px 14px; border-bottom:1px solid #dde3ea; }
  .clm-lc-table td { border:none !important; padding:6px 0; }
  .clm-lc-table td.grp { border-left:0 !important; }
  .clm-lc-table td.clm-lc-cell::before { content:attr(data-label); display:block; margin-bottom:2px;
    font-size:11px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:.5px; }
}
@media (max-width:640px) {
  .clm-ls-terr { grid-template-columns:minmax(0,1fr); }
  .clm-ls-terr-item { border-left:none; border-top:1px solid #eef1f5; }
  .clm-ls-terr-item:first-child { border-top:none; }
  .clm-ls-col .clm-tw-factors { grid-template-columns:minmax(0,1fr); }
}

/* ---------------------------------------------------------------------
10. Global Font Enforcement (keep LAST)
--------------------------------------------------------------------- */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family:"Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family:FontAwesome !important; }

sp_widget.script:
/*
 * Key Limit Swap — My Requests Server Script  v2.0
 * - "Zonal Parent" → "Zone Code": site field renamed zonal → zone_code (zonalparentcode)
 * - List rows carry donor_zone_code / donee_zone_code (shown as pills, searchable)
 * - Detail carries cascade[]: Site / Zone Code / Group Code limits before → after,
 *   only for the levels whose limit changes (shared Zone / Group Codes and the Grandparent are left out).
 *   Hidden for cancelled / rejected requests. Zone and Group limits = sum of site limits (fully-allocated model), same site filters as the request page.
 */
(function() {
    // ============================ CONFIG ============================
    var CFG = {
        SWAP:     'x_birl3_clm_key_limit_swap',
        CUSTOMER: 'x_birl3_clm_clm_customer_master1',
        SNAPSHOT: 'x_birl3_clm_clm_aging_snapshot',
        APPROVER: 'sysapproval_approver',
        SEND_BACK:'x_birl3_clm_clm_servicenow_to_sap_send_back',
        MATRIX:   'x_birl3_clm_approval_matrix',

        // Customer master columns used for the limit cascade (same as the request page)
        CM: {
            limit: 'cr_limit', zone_code: 'zonalparentcode', group: 'groupcode', grandparent: 'grand_parent',
            cg1: 'cg1', cg3: 'cg3', active: 'is_active'
        },
        KEY_CG1: 'N00',
        CONTRACTOR_CG3: 'N09',

        // Cancel button (initiator or admin, only while pending). Set false to hide it.
        ALLOW_CANCEL: true,

        // Optional filter on the send-back table's customer_type. Leave '' to match by request only.
        SEND_BACK_CUSTOMER_TYPE: '',

        // false = an approved swap with no send-back rows shows no SAP banner.
        // true  = shows "In Progress" until rows appear (use once _pushToSap is live).
        SAP_PENDING_WHEN_NO_ROWS: false,

        UPLOAD: {
            MAX_BYTES: 5 * 1024 * 1024,
            BLOCKED_EXT: ['exe', 'bat', 'cmd', 'com', 'msi', 'sh', 'ps1', 'vbs', 'js', 'jar', 'scr', 'dll']
        }
    };

    var userId  = gs.getUserID();
    var isAdmin = gs.hasRole('x_birl3_clm.admin') || gs.hasRole('admin');
    var action  = input ? input.action : null;
    data.isAdmin = isAdmin;

    // Donor-side approver fields on the swap table. Order = approval order.
    var CHAIN_FIELDS = [
        ['ls_donor_crm',      'Donor CRM'],
        ['ls_donor_tsm',      'Donor TSM'],
        ['ls_donor_rh_rmc',   'Donor RH/CH'],
        ['ls_donor_zh_key',   'Donor ZH Key'],
        ['ls_donor_zh_rmc',   'Donor ZH RMC'],
        ['ls_donor_zk_hbpd',  'ZK HBPD'],
        ['ls_donor_hsbpd',    'HS BPD'],
        ['ls_donor_hbpd',     'HBPD'],
        ['ls_donor_head_ka',  'Head KA'],
        ['ls_donor_head_rmc', 'Head RMC']
    ];

    // ============================ HELPERS ============================
    function num(gr, f) { return parseFloat(gr.getValue(f)) || 0; }
    function up(v) { return (v || '').toString().toUpperCase(); }
    function hasVal(gr, f) {
        return gr.isValidField(f) && gr.getValue(f) !== null && gr.getValue(f) !== '';
    }

    // currency values may arrive as "INR;12345.00"
    function money(v) {
        if (v === null || v === undefined || v === '') return 0;
        v = String(v);
        if (v.indexOf(';') > -1) v = v.split(';')[1];
        var n = parseFloat(v);
        return isNaN(n) ? 0 : n;
    }

    function pick(ref, fields) {
        for (var i = 0; i < fields.length; i++) {
            var v = ref.getValue(fields[i]);
            if (v) return v;
        }
        return '';
    }

    function formatGeo(code, name) {
        code = (code || '').toString().trim();
        name = (name || '').toString().trim();
        if (code && name) return name + ' (' + code + ')';
        return name || code || 'N/A';
    }

    function formatBytes(bytes) {
        var b = parseInt(bytes, 10);
        if (isNaN(b) || b <= 0) return '0 B';
        var sizes = ['B', 'KB', 'MB', 'GB'];
        var i = Math.floor(Math.log(b) / Math.log(1024));
        return parseFloat((b / Math.pow(1024, i)).toFixed(1)) + ' ' + sizes[i];
    }

    function siteOf(ref) {
        var o = { code: '', name: '', segment: '', group: '', zone_code: '', grandparent: '',
                  zone: 'N/A', region: 'N/A', depot: 'N/A' };
        if (ref && ref.isValidRecord()) {
            o.code        = pick(ref, ['customer_code_sap', 'customer_code']);
            o.name        = pick(ref, ['customer_name', 'name']);
            o.segment     = up(ref.getDisplayValue('segment') || ref.getValue('segment'));
            o.group       = ref.getValue('groupcode') || '';
            o.zone_code   = ref.getValue('zonalparentcode') || '';     // Zone Code (zonal parent)
            o.grandparent = ref.getValue('grand_parent') || '';
            o.zone        = formatGeo(ref.getValue('zone'),   ref.getValue('zone_name'));
            o.region      = formatGeo(ref.getValue('region'), ref.getValue('region_name'));
            o.depot       = formatGeo(ref.getValue('depot'),  ref.getValue('depot_name'));
        }
        return o;
    }

    // status: key (Key logic, unchanged) + internal (drives the pill colours / pending count)
    function statusOf(gr) {
        var ap = gr.getValue('approval') || '';
        var st = parseInt(gr.getValue('state'), 10);
        if (st === 7) return { key: 'cancelled', label: 'Cancelled', internal: 'cancelled' };
        if (ap === 'approved') {
            if (gr.getValue('auto_approve') == '1') return { key: 'approved', label: 'Auto-Approved', internal: 'approved' };
            return { key: 'approved', label: gr.getValue('applied') == '1' ? 'Approved & Applied' : 'Approved', internal: 'approved' };
        }
        if (ap === 'rejected')  return { key: 'rejected',  label: 'Rejected',         internal: 'rejected' };
        if (ap === 'requested') return { key: 'requested', label: 'Pending Approval', internal: 'pending' };
        return { key: 'processing', label: 'Processing', internal: 'work' };
    }

    // safe approval query - id validated, no string concatenation
    function approverGR(id) {
        var ap = new GlideRecord(CFG.APPROVER);
        if (!/^[0-9a-f]{32}$/.test(id + '')) { ap.addQuery('sys_id', 'none'); return ap; }
        var qc = ap.addQuery('sysapproval', id);
        qc.addOrCondition('document_id', id);
        return ap;
    }

    function hasAccess(gr) {
        if (isAdmin) return true;
        if (gr.getValue('opened_by') === userId) return true;
        var ap = approverGR(gr.getUniqueValue());
        ap.addQuery('approver', userId);
        ap.setLimit(1);
        ap.query();
        return ap.hasNext();
    }

    // only CRM (Cement/BPD) and TSM (RMC) may raise a swap
    function canRaise() {
        if (isAdmin) return true;
        var mx = new GlideRecord(CFG.MATRIX);
        if (!mx.isValid()) return false;
        mx.addQuery('approver_user', userId);
        mx.addQuery('customer_type', 'IN', 'Key,key,KEY,key_customer');
        var r = mx.addQuery('role_name', 'CONTAINS', 'CRM');
        r.addOrCondition('role_name', 'CONTAINS', 'TSM');
        mx.setLimit(1);
        mx.query();
        return mx.hasNext();
    }

    // ---------- Outstanding lookups ----------
    var osCache = {};
    function latestOutstanding(custId) {
        if (!custId) return null;
        if (osCache.hasOwnProperty(custId)) return osCache[custId];
        var v = null;
        var g = new GlideRecord(CFG.SNAPSHOT);
        if (g.isValid()) {
            g.addQuery('customer', custId);
            g.orderByDesc('sys_created_on');
            g.setLimit(1);
            g.query();
            if (g.next()) v = parseFloat(g.getValue('total_outstanding')) || 0;
        }
        osCache[custId] = v;
        return v;
    }
    // side = 'donee' | 'donor'. Uses the value stored on the swap, else the latest ageing snapshot.
    function outstandingFor(gr, side) {
        var f = side + '_outstanding';
        if (hasVal(gr, f)) return parseFloat(gr.getValue(f)) || 0;
        return latestOutstanding(gr.getValue(side));
    }

    // ---------- Limit cascade (Zone Code / Group Code = sum of site limits) ----------
    var sumCache = {};
    function sumSiteLimits(gp, field, code) {
        if (!code) return null;
        var key = gp + '|' + field + '|' + code;
        if (sumCache.hasOwnProperty(key)) return sumCache[key];
        var total = 0;
        var cm = new GlideRecord(CFG.CUSTOMER);
        cm.addQuery(CFG.CM.cg1, CFG.KEY_CG1);
        cm.addQuery(CFG.CM.active, true);
        cm.addQuery(CFG.CM.cg3, '!=', CFG.CONTRACTOR_CG3);   // contractor sites are not part of the Key hierarchy
        if (gp) cm.addQuery(CFG.CM.grandparent, gp);
        cm.addQuery(field, code);
        cm.query();
        while (cm.next()) total += money(cm.getValue(CFG.CM.limit));
        sumCache[key] = total;
        return total;
    }

    // before/after for one side of a Zone / Group level.
    // Applied: the master already holds the new limits, so current = after.
    // Not applied: the master still holds the old limits, so current = before.
    function levelSide(code, current, delta, applied) {
        if (current === null) return { code: code || '', before: null, after: null, delta: null };
        return applied
            ? { code: code, before: current - delta, after: current, delta: delta }
            : { code: code, before: current, after: current + delta, delta: delta };
    }

    function cascadeOf(gr, amt, applied, donorProf, doneeProf) {
        var gp = gr.getValue('grandparent_code') || '';
        var dr = siteOf(gr.donor.getRefRecord());
        var dn = siteOf(gr.donee.getRefRecord());

        var rows = [{
            key: 'site', label: 'Site Code', desc: 'Limit held in SAP',
            donor: { code: dr.code, before: donorProf.limit_before, after: donorProf.limit_after, delta: -amt },
            donee: { code: dn.code, before: doneeProf.limit_before, after: doneeProf.limit_after, delta: amt }
        }];

        [
            { key: 'zone',  label: 'Zone Code',  desc: 'Sum of its sites',      prop: 'zone_code', field: CFG.CM.zone_code },
            { key: 'group', label: 'Group Code', desc: 'Sum of its Zone Codes', prop: 'group',     field: CFG.CM.group }
        ].forEach(function(lv) {
            var drCode = dr[lv.prop], dnCode = dn[lv.prop];
            if (drCode && drCode === dnCode) return;          // shared level: nets to nil, not shown
            rows.push({
                key: lv.key, label: lv.label, desc: lv.desc,
                donor: levelSide(drCode, sumSiteLimits(gp, lv.field, drCode), -amt, applied),
                donee: levelSide(dnCode, sumSiteLimits(gp, lv.field, dnCode),  amt, applied)
            });
        });
        return rows;
    }

    // ---------- Comments / users / attachments ----------
    function getLatestApprovalComment(appGr) {
        var jGr = new GlideRecord('sys_journal_field');
        jGr.addQuery('name', CFG.APPROVER);
        jGr.addQuery('element_id', appGr.getUniqueValue());
        jGr.addQuery('element', 'IN', 'comments,work_notes');
        jGr.orderByDesc('sys_created_on');
        jGr.setLimit(1);
        jGr.query();
        if (jGr.next()) return (jGr.getValue('value') || '').trim();

        try {
            var raw = appGr.comments.getJournalEntry(1) || '';
            if (raw) {
                var lines = raw.split('\n');
                lines.shift();
                return lines.join('\n').trim();
            }
        } catch (e) {}
        return '';
    }

    var userNameCache = {};
    function getUserDisplayName(uName) {
        if (!uName) return '';
        if (userNameCache[uName] !== undefined) return userNameCache[uName];
        var uGr = new GlideRecord('sys_user');
        uGr.addQuery('user_name', uName);
        uGr.setLimit(1);
        uGr.query();
        userNameCache[uName] = uGr.next() ? (uGr.getValue('name') || uName) : uName;
        return userNameCache[uName];
    }

    function getAttachmentsForRecord(recordSysId) {
        var list = [];
        var attGr = new GlideRecord('sys_attachment');
        attGr.addQuery('table_name', CFG.SWAP);
        attGr.addQuery('table_sys_id', recordSysId);
        attGr.orderByDesc('sys_created_on');
        attGr.query();
        while (attGr.next()) {
            var fName = attGr.getValue('file_name') || '';
            var attId = attGr.getUniqueValue();
            var uploader = attGr.getValue('sys_created_by') || '';
            list.push({
                sys_id: attId,
                name: fName,
                size: formatBytes(attGr.getValue('size_bytes')),
                ext: fName.split('.').pop().toLowerCase(),
                view_url: '/sys_attachment.do?sys_id=' + attId + '&view=true',
                download_url: '/sys_attachment.do?sys_id=' + attId,
                uploaded_by: uploader,
                uploaded_by_name: getUserDisplayName(uploader),
                uploaded_on: attGr.getDisplayValue('sys_created_on') || ''
            });
        }
        return list;
    }

    // =========================================================================
    // SAP SEND-BACK (rows are matched on the swap request only)
    // =========================================================================
    function addSendBackConditions(sb, swapSysId, swapNumber) {
        var refFields = ['key_ls_request', 'u_key_ls_request', 'key_request',
                         'nt_ls_request', 'u_nt_ls_request', 'nt_request'];
        var qc = null;
        refFields.forEach(function(f) {
            if (!sb.isValidField(f)) return;
            if (!qc) qc = sb.addQuery(f, swapSysId);
            else qc.addOrCondition(f, swapSysId);
        });
        if (sb.isValidField('u_request')) {
            if (!qc) qc = sb.addQuery('u_request', swapSysId);
            else qc.addOrCondition('u_request', swapSysId);
            if (swapNumber) qc.addOrCondition('u_request', swapNumber);
        }
        return !!qc;     // false = nothing to match on, do not query
    }

    function readSendBackRows(swapSysId, swapNumber) {
        var rows = [];
        var sb = new GlideRecord(CFG.SEND_BACK);
        if (!sb.isValid()) return rows;
        if (!addSendBackConditions(sb, swapSysId, swapNumber)) return rows;
        if (CFG.SEND_BACK_CUSTOMER_TYPE && sb.isValidField('customer_type')) {
            sb.addQuery('customer_type', CFG.SEND_BACK_CUSTOMER_TYPE);
        }
        sb.orderByDesc('sys_created_on');
        sb.query();
        while (sb.next()) {
            rows.push({
                sys_id: sb.getUniqueValue(),
                status: sb.getValue('u_status') || 'Failed',
                raw_status: (sb.getValue('u_status') || '').toLowerCase(),
                last_error: isAdmin ? (sb.getValue('u_last_error') || '') : '',
                customer_code: sb.getDisplayValue('u_customer_code') || '',
                credit_segment: sb.getValue('u_credit_segment') || '',
                attempt_count: parseInt(sb.getValue('u_attempt_count'), 10) || 0,
                approved_limit: parseFloat(sb.getValue('u_approved_code_limit')) || 0,
                processed_on: sb.getDisplayValue('u_processed_on') || sb.getDisplayValue('sys_created_on') || ''
            });
        }
        return rows;
    }

    function getSapStatus(swapSysId, swapNumber, statusKey) {
        var out = {
            sap_status: 'na', sap_label: '', sap_message: '', sap_on: '', sap_attempts: 0, sap_error: '',
            sap_can_retry: false, sap_total: 0, sap_ok: 0, sap_failed: 0, sap_pending: 0
        };
        if (statusKey !== 'approved') return out;

        var rows = readSendBackRows(swapSysId, swapNumber);
        if (rows.length === 0 && !CFG.SAP_PENDING_WHEN_NO_ROWS) return out;

        var latest = {};
        rows.forEach(function(r) {
            var key = (r.customer_code || 'ALL') + '|' + (r.credit_segment || 'ALL');
            if (!latest[key]) latest[key] = r;
        });

        var total = 0, ok = 0, failed = 0, pend = 0, lastOn = '', attempts = 0, errs = [];
        for (var k in latest) {
            var lr = latest[k];
            total++;
            attempts = Math.max(attempts, lr.attempt_count);
            if (lr.raw_status === 'success' || lr.raw_status === 'processed') {
                ok++;
                if (lr.processed_on) lastOn = lr.processed_on;
            } else if (lr.raw_status === 'failed') {
                failed++;
                if (lr.last_error) errs.push(lr.customer_code + ': ' + lr.last_error);
            } else {
                pend++;
            }
        }
        out.sap_total = total; out.sap_ok = ok; out.sap_failed = failed; out.sap_pending = pend;

        if (total === 0) {
            out.sap_status = 'pending';
            out.sap_label = 'In Progress';
            out.sap_message = 'Approved. Both Donor and Donee limits are being queued in SAP.';
        } else if (failed > 0) {
            out.sap_status = 'failed';
            out.sap_label = (ok > 0) ? 'Partially Updated' : 'Failed';
            out.sap_message = (total > 1)
                ? ok + ' of ' + total + ' sites updated in SAP, ' + failed + ' failed' + (pend > 0 ? ', ' + pend + ' in progress' : '') + '. Limit reallocation not completely reflected in SAP.'
                : 'The SAP limit update failed after ' + attempts + ' attempts.';
            out.sap_error = isAdmin ? errs.join('\n') : '';
        } else if (pend > 0) {
            out.sap_status = 'pending';
            out.sap_label = 'In Progress';
            out.sap_message = ok + ' of ' + total + ' sites updated in SAP, ' + pend + ' in progress.';
        } else {
            out.sap_status = 'success';
            out.sap_label = 'Updated';
            out.sap_message = 'All ' + total + ' sites successfully updated in SAP' + (lastOn ? ' on ' + lastOn : '') + '.';
            out.sap_on = lastOn;
        }
        out.sap_attempts = attempts;
        out.sap_can_retry = (failed > 0) && isAdmin;
        return out;
    }

    function retrySapForSwap(swapSysId) {
        var res = { ok: false, message: '' };
        if (!isAdmin) { res.message = 'Only CLM admins can retry the SAP update.'; return res; }

        var rq = new GlideRecord(CFG.SWAP);
        if (!swapSysId || !rq.get(swapSysId)) { res.message = 'Request not found.'; return res; }
        if (statusOf(rq).key !== 'approved') { res.message = 'Only approved requests can be retried.'; return res; }

        var sb = new GlideRecord(CFG.SEND_BACK);
        if (!sb.isValid() || !addSendBackConditions(sb, swapSysId, rq.getValue('number') || '')) {
            res.message = 'No failed SAP transactions available to retry.';
            return res;
        }
        if (CFG.SEND_BACK_CUSTOMER_TYPE && sb.isValidField('customer_type')) {
            sb.addQuery('customer_type', CFG.SEND_BACK_CUSTOMER_TYPE);
        }
        sb.addQuery('u_status', 'Failed');
        sb.query();

        var requeued = 0;
        while (sb.next()) {
            sb.setValue('u_status', 'Pending');
            sb.setValue('u_attempt_count', 0);
            sb.setValue('u_connection_retry_count', 0);
            sb.setValue('u_last_error', 'Manual retry by ' + gs.getUserName() + ' at ' + new GlideDateTime().getDisplayValue());
            sb.update();
            requeued++;
        }
        if (requeued > 0) {
            res.ok = true;
            res.message = 'Retry submitted for ' + requeued + ' failed unit(s). Updates will re-process shortly.';
        } else {
            res.message = 'No failed SAP transactions available to retry.';
        }
        return res;
    }

    // =========================================================================
    // ROW (list) + DETAIL builders
    // =========================================================================
    function rowOf(gr) {
        var s  = statusOf(gr);
        var dn = siteOf(gr.donee.getRefRecord());
        var dr = siteOf(gr.donor.getRefRecord());
        var sap = getSapStatus(gr.getUniqueValue(), gr.getValue('number') || '', s.key);
        var created = gr.getDisplayValue('sys_created_on') || '';

        return {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            gp: gr.getValue('grandparent_code') || '',
            group: gr.getValue('group_code') || '',
            swap_type: gr.getDisplayValue('swap_type') || '',
            amount: num(gr, 'requested_amount'),
            status_key: s.key,
            status_label: s.label,
            internal: s.internal,
            requester: gr.getDisplayValue('opened_by'),
            created: created,
            created_on: created.split(' ')[0],

            donee: dn.code,
            donee_site: dn.code ? (dn.code + ' — ' + dn.name) : dn.name,
            donee_segment: up(gr.getDisplayValue('donee_segment') || gr.getValue('donee_segment') || dn.segment),
            donee_zone_code: dn.zone_code,
            donee_group: dn.group,
            donee_zone: dn.zone, donee_region: dn.region, donee_depot: dn.depot,
            donee_outstanding: outstandingFor(gr, 'donee'),

            donor: dr.code,
            donor_site: dr.code ? (dr.code + ' — ' + dr.name) : dr.name,
            donor_segment: up(gr.getDisplayValue('donor_segment') || gr.getValue('donor_segment') || dr.segment),
            donor_zone_code: dr.zone_code,
            donor_group: dr.group,
            donor_zone: dr.zone, donor_region: dr.region, donor_depot: dr.depot,
            donor_outstanding: outstandingFor(gr, 'donor'),

            sap_status: sap.sap_status, sap_label: sap.sap_label, sap_message: sap.sap_message,
            sap_on: sap.sap_on, sap_attempts: sap.sap_attempts, sap_error: sap.sap_error,
            sap_can_retry: sap.sap_can_retry, sap_total: sap.sap_total, sap_ok: sap.sap_ok,
            sap_failed: sap.sap_failed, sap_pending: sap.sap_pending
        };
    }

    function ageingHistory(custId) {
        var hist = [];
        if (!custId) return hist;
        var g = new GlideRecord(CFG.SNAPSHOT);
        if (!g.isValid()) return hist;
        g.addQuery('customer', custId);
        g.orderByDesc('sys_created_on');
        g.setLimit(6);
        g.query();
        while (g.next()) {
            hist.push({
                date:   (g.getDisplayValue('snapshot_month') || '').split(' ')[0],
                total:  parseFloat(g.getValue('total_outstanding') || 0),
                b0_30:  parseFloat(g.getValue('b0_30')  || g.getValue('bucket_0_30_days')   || 0),
                b31_45: parseFloat(g.getValue('b31_45') || g.getValue('bucket_31_45_days')  || 0),
                b46_60: parseFloat(g.getValue('b46_60') || g.getValue('bucket_46_60_days')  || 0),
                b61_75: parseFloat(g.getValue('b61_75') || g.getValue('bucket_61_75_days')  || 0),
                b76_90: parseFloat(g.getValue('b76_90') || g.getValue('bucket_76_90_days')  || 0),
                b_gt90: parseFloat(g.getValue('b_gt90') || g.getValue('bucket_91_120_days') || 0)
            });
        }
        return hist;
    }

    // one side (donee/donor) of the swap
    function profileOf(gr, side, limitBefore, limitAfter) {
        var ref = side === 'donee' ? gr.donee.getRefRecord() : gr.donor.getRefRecord();
        var o = siteOf(ref);
        var os = outstandingFor(gr, side);
        return {
            name: o.name || 'N/A',
            code: o.code || 'N/A',
            segment: up(gr.getDisplayValue(side + '_segment') || gr.getValue(side + '_segment') || o.segment) || 'N/A',
            zone_code: o.zone_code,
            group: o.group,
            zone: o.zone, region: o.region, depot: o.depot,
            limit_before: limitBefore,
            limit_after: limitAfter,
            outstanding: os === null ? 0 : os,
            history: ageingHistory(gr.getValue(side))
        };
    }

    function loadDetail(id) {
        var gr = new GlideRecord(CFG.SWAP);
        if (!id || !gr.get(id) || !hasAccess(gr)) return null;

        var base = rowOf(gr);
        var s = statusOf(gr);
        var applied = gr.getValue('applied') == '1';
        var amt = num(gr, 'requested_amount');
        var isCancelled = s.key === 'cancelled';

        // role per approver, from the resolved donor fields
        var roleByUser = {};
        CHAIN_FIELDS.forEach(function(cf) {
            if (!gr.isValidField(cf[0])) return;
            var u = gr.getValue(cf[0]);
            if (!u) return;
            roleByUser[u] = roleByUser[u] ? (roleByUser[u] + ' / ' + cf[1]) : cf[1];
        });

        // approval records
        var trail = [], stateByUser = {}, seq = 0;
        var ap = approverGR(id);
        ap.orderBy('sys_created_on');
        ap.query();
        while (ap.next()) {
            seq++;
            var uid = ap.getValue('approver');
            var st  = ap.getValue('state');
            stateByUser[uid] = st;
            var role = roleByUser[uid] ||
                (ap.isValidField('approval_reason') && ap.getValue('approval_reason')) || 'Approver';
            trail.push({
                seq: seq,
                updated_ts: new GlideDateTime(ap.getValue('sys_updated_on')).getNumericValue(),
                approver: ap.getDisplayValue('approver') || 'System Approver',
                is_me: uid === userId,
                role: role,
                state: ap.getDisplayValue('state'),
                state_value: st,
                comments: getLatestApprovalComment(ap),
                updated: st === 'requested' ? '' : ap.getDisplayValue('sys_updated_on')
            });
        }

        // progress chain from the resolved donor approvers (includes approvers not reached yet)
        var chain = [{
            role: 'Initiator', name: gr.getDisplayValue('opened_by'),
            cls: 'completed', label: 'Submitted', is_me: gr.getValue('opened_by') === userId
        }];
        CHAIN_FIELDS.forEach(function(cf) {
            if (!gr.isValidField(cf[0])) return;
            var u = gr.getValue(cf[0]);
            if (!u) return;
            var st = stateByUser[u];
            var cls, label;
            if (st === 'approved')       { cls = 'completed'; label = 'Approved'; }
            else if (st === 'rejected')  { cls = 'rejected';  label = 'Rejected'; }
            else if (st === 'cancelled') { cls = 'rejected';  label = 'Cancelled'; }
            else if (st === 'requested' && !isCancelled) { cls = 'current'; label = 'Pending Action'; }
            else                         { cls = 'pending';   label = 'Waiting'; }
            chain.push({ role: cf[1], name: gr.getDisplayValue(cf[0]), cls: cls, label: label, is_me: u === userId });
        });

        // limits: stored before/after once applied, otherwise projected from the request snapshot
        var doneeBefore = applied ? num(gr, 'donee_limit_before') : num(gr, 'donee_current_limit');
        var doneeAfter  = applied ? num(gr, 'donee_limit_after')  : num(gr, 'donee_current_limit') + amt;
        var donorBefore = applied ? num(gr, 'donor_limit_before') : num(gr, 'donor_current_limit');
        var donorAfter  = applied ? num(gr, 'donor_limit_after')  : num(gr, 'donor_current_limit') - amt;

        var detail = base;
        detail.justification = gr.getValue('justification') || gr.getValue('description') || '';
        detail.applied = applied;
        detail.auto_approve = gr.getValue('auto_approve') == '1';
        detail.donee_profile = profileOf(gr, 'donee', doneeBefore, doneeAfter);
        detail.donor_profile = profileOf(gr, 'donor', donorBefore, donorAfter);
        detail.cascade = (isCancelled || s.key === 'rejected') ? [] : cascadeOf(gr, amt, applied, detail.donor_profile, detail.donee_profile);
        detail.trail = trail;
        detail.chain = chain;
        detail.attachments = getAttachmentsForRecord(id);
        detail.sendBackList = readSendBackRows(id, base.number || '');
        detail.can_cancel = CFG.ALLOW_CANCEL &&
            (isAdmin || gr.getValue('opened_by') === userId) &&
            (gr.getValue('approval') === 'requested') && !applied && !isCancelled;
        return detail;
    }

    function listRows(scope) {
        var rows = [];
        var gr = new GlideRecord(CFG.SWAP);
        if (!(scope === 'all' && isAdmin)) gr.addQuery('opened_by', userId);
        gr.orderByDesc('sys_created_on');
        gr.setLimit(500);
        gr.query();
        while (gr.next()) rows.push(rowOf(gr));
        return rows;
    }

    // =========================================================================
    // ACTIONS
    // =========================================================================
    data.canRaise = canRaise();

    if (action === 'list') {
        data.rows = listRows(input.scope);
        return;
    }

    if (action === 'detail') {
        data.detail = loadDetail(input.sys_id);
        if (!data.detail) data.serverError = 'This request was not found, or you do not have access to it.';
        return;
    }

    if (action === 'get_sap_status' || action === 'retry_sap') {
        var sg = new GlideRecord(CFG.SWAP);
        if (!input.sys_id || !sg.get(input.sys_id) || !hasAccess(sg)) {
            data.serverError = 'This request was not found, or you do not have access to it.';
            return;
        }
        if (action === 'retry_sap') data.retryResult = retrySapForSwap(input.sys_id);
        var sNum = sg.getValue('number') || '';
        data.sap = getSapStatus(input.sys_id, sNum, statusOf(sg).key);
        data.sendBackList = readSendBackRows(input.sys_id, sNum);
        return;
    }

    if (action === 'upload_document') {
        var ug = new GlideRecord(CFG.SWAP);
        if (!input.sys_id || !ug.get(input.sys_id) || !hasAccess(ug)) {
            data.serverError = 'This request was not found, or you do not have access to it.';
            return;
        }
        var fName = (input.fileName || '').toString();
        var b64   = (input.fileData || '').toString();
        var ext   = fName.indexOf('.') > -1 ? fName.split('.').pop().toLowerCase() : '';
        if (!fName || !b64) { data.serverError = 'No file received.'; return; }
        if (CFG.UPLOAD.BLOCKED_EXT.indexOf(ext) > -1) { data.serverError = 'This file type is not allowed.'; return; }
        if (Math.floor(b64.length * 3 / 4) > CFG.UPLOAD.MAX_BYTES) { data.serverError = 'File size exceeds the 5MB limit.'; return; }

        try {
            new GlideSysAttachment().writeBase64(ug, fName, input.fileType || 'application/octet-stream', b64);
        } catch (e) {
            gs.error('Key Limit Swap upload error (' + fName + '): ' + e.message);
            data.serverError = 'Failed to upload the document.';
            return;
        }
        data.attachments = getAttachmentsForRecord(input.sys_id);
        return;
    }

    if (action === 'cancel_swap') {
        data.success = false;
        if (!CFG.ALLOW_CANCEL) { data.message = 'Cancelling is not enabled.'; return; }

        var cg = new GlideRecord(CFG.SWAP);
        if (!input.sys_id || !cg.get(input.sys_id) || !hasAccess(cg)) {
            data.message = 'This request was not found, or you do not have access to it.';
            return;
        }
        if (!(isAdmin || cg.getValue('opened_by') === userId)) {
            data.message = 'Only the initiator can cancel this request.';
            return;
        }
        if (cg.getValue('approval') !== 'requested' || cg.getValue('applied') == '1' ||
            parseInt(cg.getValue('state'), 10) === 7) {
            data.message = 'Only a pending request can be cancelled.';
            return;
        }

        cg.setValue('approval', 'rejected');
        cg.setValue('state', '7');
        if (cg.isValidField('active')) cg.setValue('active', false);
        cg.comments = 'System Action: Key limit swap request cancelled by ' + gs.getUserDisplayName() + '.';
        cg.update();

        var pend = approverGR(input.sys_id);
        pend.addQuery('state', 'requested');
        pend.query();
        while (pend.next()) {
            pend.setValue('state', 'cancelled');
            pend.update();
        }
        data.success = true;
        return;
    }

    // ---------- initial load ----------
    data.rows = listRows('mine');
    var sid = $sp.getParameter('sys_id');
    if (sid) {
        data.detail = loadDetail(sid);
        if (!data.detail) data.linkError = 'The requested swap was not found, or you do not have access to it.';
    }
})();
